<?php
/** Read-only writer exclusion verification. Never changes accounts, grants or services. */
require_once __DIR__.'/review-account-evidence.php';
function releasePrincipal(string $user,string $host):string {return $user.'@'.$host;}
function releasePrincipalUser(string $principal):string {$i=strrpos($principal,'@');return $i===false?$principal:substr($principal,0,$i);}
function releaseFenceValidate(array $inventory,array $plan,string $current,array $sessions):array {
    $writers=$plan['writer_accounts']??[];$trusted=$plan['trusted_privileged_accounts']??[];if(!$writers||!in_array($current,$trusted,true))throw new RuntimeException('RELEASE_WRITER_PLAN_REQUIRED');$seen=[];$allWriterNames=[];
    foreach($inventory as$a){$who=$a['principal'];if(!$a['can_write_sulbprod'])continue;$allWriterNames[]=releasePrincipalUser($who);if(in_array($who,$trusted,true))continue;if($a['locked']&&!in_array($who,$writers,true))continue;$seen[]=$who;if(!in_array($who,$writers,true))throw new RuntimeException('RELEASE_UNREVIEWED_DATABASE_WRITER');if(!$a['locked'])throw new RuntimeException('RELEASE_DATABASE_WRITER_NOT_EXCLUDED');}
    foreach($writers as$who)if(!in_array($who,$seen,true))throw new RuntimeException('RELEASE_WRITER_PLAN_DRIFT');$names=$allWriterNames;foreach($sessions as$s)if(($s['is_current']??false)!==true&&(($s['schema']??null)==='sulbprod'||in_array($s['user']??releasePrincipalUser($s['principal']??''),$names,true)))throw new RuntimeException('RELEASE_OLD_DATABASE_CLIENTS_NOT_DRAINED');
    return ['ordinary_writer_accounts_excluded'=>count($seen),'trusted_dba_exception_count'=>count($trusted),'direct_writer_exclusion'=>'VERIFIED_ACCOUNT_STATUS_AND_DRAIN','privileged_dbas_are_trusted_maintenance_operators'=>true];
}
function releaseFenceInventory(PDO $pdo):array {
    $process=false;foreach($pdo->query('SHOW GRANTS FOR CURRENT_USER')->fetchAll(PDO::FETCH_COLUMN)as$g)if(preg_match('/^GRANT (.+) ON \*\.\* TO /i',$g,$m)&&preg_match('/(?:^|,\s*)(PROCESS|ALL PRIVILEGES)(?:,|$)/i',$m[1]))$process=true;if(!$process)throw new RuntimeException('RELEASE_PROCESS_VISIBILITY_REQUIRED');
    if((int)$pdo->query('SELECT COUNT(*) FROM mysql.role_edges')->fetchColumn()!==0||trim((string)$pdo->query('SELECT @@mandatory_roles')->fetchColumn())!=='')throw new RuntimeException('RELEASE_UNREVIEWED_INHERITED_ROLE_GRAPH');
    $inventory=[];$flags=['Insert_priv','Update_priv','Delete_priv','Create_priv','Drop_priv','Alter_priv','Grant_priv','Trigger_priv','Create_routine_priv','Alter_routine_priv','Event_priv','Execute_priv','Super_priv'];
    foreach($pdo->query('SELECT User,Host,account_locked,'.implode(',',$flags).',Create_user_priv FROM mysql.user')->fetchAll(PDO::FETCH_ASSOC)as$a){$who=releasePrincipal($a['User'],$a['Host']);$inventory[$who]=['principal'=>$who,'locked'=>$a['account_locked']==='Y','can_write_sulbprod'=>false];foreach(array_merge($flags,['Create_user_priv'])as$f)if($a[$f]==='Y')$inventory[$who]['can_write_sulbprod']=true;}
    foreach($pdo->query('SELECT USER,HOST FROM mysql.global_grants')->fetchAll(PDO::FETCH_ASSOC)as$a){$who=releasePrincipal($a['USER'],$a['HOST']);if(!isset($inventory[$who]))throw new RuntimeException('RELEASE_ORPHAN_DYNAMIC_PRIVILEGE');$inventory[$who]['can_write_sulbprod']=true;}
    foreach($pdo->query("SELECT User,Host,".implode(',',array_diff($flags,['Super_priv']))." FROM mysql.db WHERE 'sulbprod' LIKE Db")->fetchAll(PDO::FETCH_ASSOC)as$a){$who=releasePrincipal($a['User'],$a['Host']);if(!isset($inventory[$who]))throw new RuntimeException('RELEASE_ORPHAN_PRIVILEGE_PRINCIPAL');foreach(array_diff($flags,['Super_priv'])as$f)if($a[$f]==='Y')$inventory[$who]['can_write_sulbprod']=true;}
    foreach(['tables_priv'=>'Table_priv','columns_priv'=>'Column_priv']as$table=>$column)foreach($pdo->query("SELECT User,Host,`$column` privileges_set FROM mysql.`$table` WHERE Db='sulbprod'")->fetchAll(PDO::FETCH_ASSOC)as$a){$who=releasePrincipal($a['User'],$a['Host']);if(!isset($inventory[$who]))throw new RuntimeException('RELEASE_ORPHAN_PRIVILEGE_PRINCIPAL');if(preg_match('/(?:^|,)(Insert|Update|Delete|Create|Drop|Alter|Trigger|Grant)(?:,|$)/i',$a['privileges_set']))$inventory[$who]['can_write_sulbprod']=true;}
    foreach($pdo->query("SELECT User,Host,Proc_priv privileges_set FROM mysql.procs_priv WHERE Db='sulbprod'")->fetchAll(PDO::FETCH_ASSOC)as$a){$who=releasePrincipal($a['User'],$a['Host']);if(!isset($inventory[$who]))throw new RuntimeException('RELEASE_ORPHAN_PRIVILEGE_PRINCIPAL');$inventory[$who]['can_write_sulbprod']=true;}
    if((int)$pdo->query("SELECT COUNT(*) FROM information_schema.EVENTS WHERE EVENT_SCHEMA='sulbprod' AND STATUS='ENABLED'")->fetchColumn()!==0)throw new RuntimeException('RELEASE_UNREVIEWED_DATABASE_EVENTS');
    if((int)$pdo->query('SELECT COUNT(*) FROM mysql.proxies_priv')->fetchColumn()!==0)throw new RuntimeException('RELEASE_UNREVIEWED_PROXY_PRIVILEGES');return array_values($inventory);
}
function verifyReleaseFence(PDO $pdo,array $release):array {
    $dir='/run/sulb-release.fence';if(!is_dir($dir)||is_link($dir)||realpath($dir)!==$dir||fileowner($dir)!==0||(fileperms($dir)&0077)!==0)throw new RuntimeException('RELEASE_ROOT_OWNED_FENCE_REQUIRED');
    $a=$pdo->query('SELECT DATABASE() db,@@server_uuid uuid,VERSION() version,@@version_comment family,CURRENT_USER() principal,CONNECTION_ID() cid')->fetch(PDO::FETCH_ASSOC);if($a['db']!=='sulbprod'||!str_starts_with($a['version'],'8.4.')||stripos($a['family'],'Percona')===false)throw new RuntimeException('RELEASE_FENCE_SERVER_IDENTITY');
    $sessions=[];foreach($pdo->query('SELECT ID,USER,HOST,DB FROM information_schema.PROCESSLIST')->fetchAll(PDO::FETCH_ASSOC)as$s){$sessions[]=['user'=>$s['USER'],'principal'=>$s['USER'].'@'.preg_replace('/:\d+$/','',$s['HOST']),'schema'=>$s['DB'],'is_current'=>(string)$s['ID']===(string)$a['cid']];if((string)$s['ID']!==(string)$a['cid']&&$s['USER']===releasePrincipalUser($a['principal']))throw new RuntimeException('RELEASE_OTHER_PRIVILEGED_CLIENT');}
    $e=releaseFenceValidate(releaseFenceInventory($pdo),$release['write_fence_plan']??[],$a['principal'],$sessions);$e['server_uuid']=$a['uuid'];$e['database_account']=$a['principal'];return $e;
}
